import type { jsPDF } from "jspdf";
export function registerClientReportFonts(pdf: jsPDF) {
  pdf.addFileToVFS("ClientReportSans-Regular.ttf", "");
  pdf.addFont("ClientReportSans-Regular.ttf", "ClientReportSans", "normal");
  pdf.addFileToVFS("ClientReportSans-Bold.ttf", "");
  pdf.addFont("ClientReportSans-Bold.ttf", "ClientReportSans", "bold");
}
